// Generated by scripts/generate-articles.ts. Do not edit.
export default {"html":"<aside class=\"msg alert\"><span class=\"msg-symbol\">!</span><div class=\"msg-content\"><p data-line=\"1\" class=\"code-line\">This article was drafted by generative AI from <a href=\"https://www.youtube.com/shorts/jljkjmxZ4AM\" target=\"_blank\" rel=\"noopener noreferrer\">https://www.youtube.com/shorts/jljkjmxZ4AM</a> as source material, then reviewed and edited by the author.</p>\n</div></aside>\n<p data-line=\"4\" class=\"code-line\">Angular Signals are central to efficient application state management. Choosing between <code>linked signal</code> and <code>computed signal</code> is an important decision. This article explains the differences in detail.</p>\n<h2 id=\"signals-basics-recap\" data-line=\"6\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#signals-basics-recap\" aria-hidden=\"true\"></a> Signals basics recap</h2>\n<p data-line=\"8\" class=\"code-line\">First, a quick review. Signals are the foundation of Angular's new reactive programming model. Basic usage looks like this:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"10\"><span class=\"line\"><span style=\"color:#a0aab5\">// 基本的なsignal</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> count</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">0</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">// computed signal</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> doubledCount</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> computed</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#B392F0\"> count</span><span style=\"color:#E1E4E8\">() </span><span style=\"color:#F97583\">*</span><span style=\"color:#79B8FF\"> 2</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">// effect</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">effect</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">`カウントが変更されました: ${</span><span style=\"color:#B392F0\">count</span><span style=\"color:#9ECBFF\">()</span><span style=\"color:#9ECBFF\">}`</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"23\" class=\"code-line\">Signals offer a simple API for state management. Still, the difference between <code>linked signal</code> and <code>computed signal</code> can be surprisingly subtle.</p>\n<h2 id=\"signal%2C-computed-signal%2C-and-linked-signal\" data-line=\"25\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#signal%2C-computed-signal%2C-and-linked-signal\" aria-hidden=\"true\"></a> Signal, computed signal, and linked signal</h2>\n<p data-line=\"27\" class=\"code-line\">Angular Signals have three main types. Let us look at each.</p>\n<h3 id=\"signal-(basic-signal)\" data-line=\"29\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#signal-(basic-signal)\" aria-hidden=\"true\"></a> Signal (basic signal)</h3>\n<p data-line=\"31\" class=\"code-line\">A Signal is the basic building block of Angular reactive programming. It holds a single value, supports reads and updates, and lets other Signals or UI components watch changes.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"33\"><span class=\"line\"><span style=\"color:#a0aab5\">// 基本的なsignalの使用例</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> count</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">0</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">// 値の読み取り</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#B392F0\">count</span><span style=\"color:#E1E4E8\">()); </span><span style=\"color:#a0aab5\">// 出力: 0</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">// 値の更新</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">count.</span><span style=\"color:#B392F0\">set</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">1</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#B392F0\">count</span><span style=\"color:#E1E4E8\">()); </span><span style=\"color:#a0aab5\">// 出力: 1</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">// 値の更新（現在の値に基づく）</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">count.</span><span style=\"color:#B392F0\">update</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">value</span><span style=\"color:#F97583\"> =&gt;</span><span style=\"color:#E1E4E8\"> value </span><span style=\"color:#F97583\">+</span><span style=\"color:#79B8FF\"> 1</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#B392F0\">count</span><span style=\"color:#E1E4E8\">()); </span><span style=\"color:#a0aab5\">// 出力: 2</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"49\" class=\"code-line\">Use Signals as the basic unit for application state. They fit simple state management.</p>\n<h3 id=\"computed-signal\" data-line=\"51\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#computed-signal\" aria-hidden=\"true\"></a> Computed Signal</h3>\n<p data-line=\"53\" class=\"code-line\">A Computed Signal derives a value from other Signals. When dependencies change, it recomputes automatically. It is read-only—you cannot set it directly—and you cannot access the previous value.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"55\"><span class=\"line\"><span style=\"color:#a0aab5\">// computed signalの使用例</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> firstName</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'太郎'</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> lastName</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'山田'</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> fullName</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> computed</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#9ECBFF\"> `${</span><span style=\"color:#B392F0\">firstName</span><span style=\"color:#9ECBFF\">()</span><span style=\"color:#9ECBFF\">} ${</span><span style=\"color:#B392F0\">lastName</span><span style=\"color:#9ECBFF\">()</span><span style=\"color:#9ECBFF\">}`</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#B392F0\">fullName</span><span style=\"color:#E1E4E8\">()); </span><span style=\"color:#a0aab5\">// 出力: 太郎 山田</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">firstName.</span><span style=\"color:#B392F0\">set</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'一郎'</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#B392F0\">fullName</span><span style=\"color:#E1E4E8\">()); </span><span style=\"color:#a0aab5\">// 出力: 一郎 山田</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"67\" class=\"code-line\">Computed Signals recompute only when a dependency changes, which matters for performance. They are especially useful in cases like:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"69\"><span class=\"line\"><span style=\"color:#a0aab5\">// 内部的な動作の例</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> a</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">1</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> b</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">2</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> c</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> computed</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'再計算が実行されました'</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  return</span><span style=\"color:#B392F0\"> a</span><span style=\"color:#E1E4E8\">() </span><span style=\"color:#F97583\">+</span><span style=\"color:#B392F0\"> b</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">// 初回の読み取り</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#B392F0\">c</span><span style=\"color:#E1E4E8\">()); </span><span style=\"color:#a0aab5\">// 出力: 3, \"再計算が実行されました\"</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">// aの値が変更された場合</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">a.</span><span style=\"color:#B392F0\">set</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">2</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#B392F0\">c</span><span style=\"color:#E1E4E8\">()); </span><span style=\"color:#a0aab5\">// 出力: 4, \"再計算が実行されました\"</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">// bの値が変更された場合</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">b.</span><span style=\"color:#B392F0\">set</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">3</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#B392F0\">c</span><span style=\"color:#E1E4E8\">()); </span><span style=\"color:#a0aab5\">// 出力: 5, \"再計算が実行されました\"</span></span>\n<span class=\"line\"></span></code></pre></div><h3 id=\"linked-signal\" data-line=\"90\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#linked-signal\" aria-hidden=\"true\"></a> Linked Signal</h3>\n<p data-line=\"92\" class=\"code-line\">Linked Signal is more flexible than Computed Signal. You can access the previous value and set the value directly. It also handles more complex state transitions and external events.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"94\"><span class=\"line\"><span style=\"color:#a0aab5\">// linked signalの使用例</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> inputText</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">''</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> filteredText</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> linkedSignal</span><span style=\"color:#E1E4E8\">(</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  inputText,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  (</span><span style=\"color:#FFAB70\">current</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#FFAB70\">previous</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">    // 現在の値と以前の値にアクセスできる</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    if</span><span style=\"color:#E1E4E8\"> (current.</span><span style=\"color:#79B8FF\">length</span><span style=\"color:#F97583\"> &lt;</span><span style=\"color:#E1E4E8\"> previous.</span><span style=\"color:#79B8FF\">length</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">      return</span><span style=\"color:#E1E4E8\"> current; </span><span style=\"color:#a0aab5\">// 文字が削除された場合はそのまま</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    }</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    return</span><span style=\"color:#E1E4E8\"> current.</span><span style=\"color:#B392F0\">toUpperCase</span><span style=\"color:#E1E4E8\">(); </span><span style=\"color:#a0aab5\">// 文字が追加された場合は大文字に</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"109\" class=\"code-line\">Internally, whenever the source Signal changes, the callback runs with both the current and previous values. The return value becomes the new linked value.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"111\"><span class=\"line\"><span style=\"color:#a0aab5\">// 内部的な動作の例</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> source</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">0</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> linked</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> linkedSignal</span><span style=\"color:#E1E4E8\">(</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  source,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  (</span><span style=\"color:#FFAB70\">current</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#FFAB70\">previous</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">`現在の値: ${</span><span style=\"color:#E1E4E8\">current</span><span style=\"color:#9ECBFF\">}, 以前の値: ${</span><span style=\"color:#E1E4E8\">previous</span><span style=\"color:#9ECBFF\">}`</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    return</span><span style=\"color:#E1E4E8\"> current </span><span style=\"color:#F97583\">*</span><span style=\"color:#79B8FF\"> 2</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">// 値の変更</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">source.</span><span style=\"color:#B392F0\">set</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">1</span><span style=\"color:#E1E4E8\">); </span><span style=\"color:#a0aab5\">// 出力: \"現在の値: 1, 以前の値: 0\"</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#B392F0\">linked</span><span style=\"color:#E1E4E8\">()); </span><span style=\"color:#a0aab5\">// 出力: 2</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">source.</span><span style=\"color:#B392F0\">set</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">2</span><span style=\"color:#E1E4E8\">); </span><span style=\"color:#a0aab5\">// 出力: \"現在の値: 2, 以前の値: 1\"</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#B392F0\">linked</span><span style=\"color:#E1E4E8\">()); </span><span style=\"color:#a0aab5\">// 出力: 4</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"which-should-you-use%3F-concrete-criteria\" data-line=\"130\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#which-should-you-use%3F-concrete-criteria\" aria-hidden=\"true\"></a> Which should you use? Concrete criteria</h2>\n<p data-line=\"132\" class=\"code-line\">Which one should you pick in real development? Here are concrete criteria:</p>\n<h3 id=\"when-to-use-computed-signal\" data-line=\"134\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#when-to-use-computed-signal\" aria-hidden=\"true\"></a> When to use computed signal</h3>\n<p data-line=\"136\" class=\"code-line\">Computed Signal fits simple calculations and transforms. Use it when you derive a value from other Signals and do not need the previous value. It also suits performance-sensitive cases.</p>\n<p data-line=\"138\" class=\"code-line\">Examples:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"140\"><span class=\"line\"><span style=\"color:#a0aab5\">// 合計金額の計算</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> items</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">([</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  { name: </span><span style=\"color:#9ECBFF\">'りんご'</span><span style=\"color:#E1E4E8\">, price: </span><span style=\"color:#79B8FF\">100</span><span style=\"color:#E1E4E8\"> },</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  { name: </span><span style=\"color:#9ECBFF\">'バナナ'</span><span style=\"color:#E1E4E8\">, price: </span><span style=\"color:#79B8FF\">200</span><span style=\"color:#E1E4E8\"> }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">]);</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> total</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> computed</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> </span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  items</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">reduce</span><span style=\"color:#E1E4E8\">((</span><span style=\"color:#FFAB70\">sum</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#FFAB70\">item</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> sum </span><span style=\"color:#F97583\">+</span><span style=\"color:#E1E4E8\"> item.price, </span><span style=\"color:#79B8FF\">0</span><span style=\"color:#E1E4E8\">)</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"151\" class=\"code-line\">This computes the total price of items in a list. When items are added or removed, the total updates automatically. Simple aggregation is a Computed Signal sweet spot.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"153\"><span class=\"line\"><span style=\"color:#a0aab5\">// フィルタリング</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> searchTerm</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">''</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> filteredItems</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> computed</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> </span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  items</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">filter</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">item</span><span style=\"color:#F97583\"> =&gt;</span><span style=\"color:#E1E4E8\"> </span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    item.name.</span><span style=\"color:#B392F0\">includes</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#B392F0\">searchTerm</span><span style=\"color:#E1E4E8\">())</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  )</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"163\" class=\"code-line\">This filters items by search keyword. When the keyword changes, the filtered list updates. Deriving new values from other Signals is a typical Computed Signal use case.</p>\n<h3 id=\"when-to-use-linked-signal\" data-line=\"165\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#when-to-use-linked-signal\" aria-hidden=\"true\"></a> When to use linked signal</h3>\n<p data-line=\"167\" class=\"code-line\">Linked Signal fits when you want different behavior based on the previous value, or when external events should set the value directly. It also suits complex state transitions and async results.</p>\n<p data-line=\"169\" class=\"code-line\">Examples:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"171\"><span class=\"line\"><span style=\"color:#a0aab5\">// Undo/Redo機能</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> history</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> linkedSignal</span><span style=\"color:#E1E4E8\">(</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  currentState,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  (</span><span style=\"color:#FFAB70\">current</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#FFAB70\">previous</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    if</span><span style=\"color:#E1E4E8\"> (current.action </span><span style=\"color:#F97583\">===</span><span style=\"color:#9ECBFF\"> 'undo'</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">      return</span><span style=\"color:#E1E4E8\"> previous; </span><span style=\"color:#a0aab5\">// 前の状態に戻る</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    }</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    return</span><span style=\"color:#E1E4E8\"> current; </span><span style=\"color:#a0aab5\">// 新しい状態に進む</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"184\" class=\"code-line\">This implements undo/redo over user actions. Compare current and previous state: on undo, go back; on redo, advance. When you need previous state to branch logic, Linked Signal is the right tool.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"186\"><span class=\"line\"><span style=\"color:#a0aab5\">// 非同期処理の状態管理</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> apiState</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> linkedSignal</span><span style=\"color:#E1E4E8\">(</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  fetchState,</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  async</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#FFAB70\">current</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#FFAB70\">previous</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    if</span><span style=\"color:#E1E4E8\"> (current.status </span><span style=\"color:#F97583\">===</span><span style=\"color:#9ECBFF\"> 'loading'</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">      try</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">        const</span><span style=\"color:#79B8FF\"> data</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> await</span><span style=\"color:#B392F0\"> fetchData</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">        return</span><span style=\"color:#E1E4E8\"> { status: </span><span style=\"color:#9ECBFF\">'success'</span><span style=\"color:#E1E4E8\">, data };</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      } </span><span style=\"color:#F97583\">catch</span><span style=\"color:#E1E4E8\"> (error) {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">        return</span><span style=\"color:#E1E4E8\"> { status: </span><span style=\"color:#9ECBFF\">'error'</span><span style=\"color:#E1E4E8\">, error };</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    }</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    return</span><span style=\"color:#E1E4E8\"> current;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"204\" class=\"code-line\">This manages API call state. Handle loading, success, and error appropriately. Linked Signal fits async results and state changes driven by external events.</p>\n<h2 id=\"practical-example%3A-form-validation\" data-line=\"206\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#practical-example%3A-form-validation\" aria-hidden=\"true\"></a> Practical example: form validation</h2>\n<p data-line=\"208\" class=\"code-line\">A common project example is form validation. Linked Signal can manage form state efficiently.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"210\"><span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> formData</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  email: </span><span style=\"color:#9ECBFF\">''</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  password: </span><span style=\"color:#9ECBFF\">''</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">// バリデーション状態</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> validationState</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> linkedSignal</span><span style=\"color:#E1E4E8\">(</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  formData,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  (</span><span style=\"color:#FFAB70\">current</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#FFAB70\">previous</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    const</span><span style=\"color:#79B8FF\"> errors</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      email: current.email </span><span style=\"color:#F97583\">?</span><span style=\"color:#9ECBFF\"> ''</span><span style=\"color:#F97583\"> :</span><span style=\"color:#9ECBFF\"> 'メールアドレスは必須です'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      password: current.password.</span><span style=\"color:#79B8FF\">length</span><span style=\"color:#F97583\"> &gt;=</span><span style=\"color:#79B8FF\"> 8</span><span style=\"color:#F97583\"> ?</span><span style=\"color:#9ECBFF\"> ''</span><span style=\"color:#F97583\"> :</span><span style=\"color:#9ECBFF\"> 'パスワードは8文字以上必要です'</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    };</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    </span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">    // 以前の状態と比較して、エラーメッセージを更新</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    if</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#79B8FF\">JSON</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">stringify</span><span style=\"color:#E1E4E8\">(errors) </span><span style=\"color:#F97583\">!==</span><span style=\"color:#79B8FF\"> JSON</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">stringify</span><span style=\"color:#E1E4E8\">(previous?.errors)) {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">      return</span><span style=\"color:#E1E4E8\"> { </span><span style=\"color:#F97583\">...</span><span style=\"color:#E1E4E8\">current, errors };</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    }</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    return</span><span style=\"color:#E1E4E8\"> previous;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">// フォームの送信状態</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> submitState</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> linkedSignal</span><span style=\"color:#E1E4E8\">(</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  validationState,</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  async</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#FFAB70\">current</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#FFAB70\">previous</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    if</span><span style=\"color:#E1E4E8\"> (current.isSubmitting) {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">      try</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">        await</span><span style=\"color:#B392F0\"> submitForm</span><span style=\"color:#E1E4E8\">(current);</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">        return</span><span style=\"color:#E1E4E8\"> { </span><span style=\"color:#F97583\">...</span><span style=\"color:#E1E4E8\">current, isSubmitting: </span><span style=\"color:#79B8FF\">false</span><span style=\"color:#E1E4E8\">, isSubmitted: </span><span style=\"color:#79B8FF\">true</span><span style=\"color:#E1E4E8\"> };</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      } </span><span style=\"color:#F97583\">catch</span><span style=\"color:#E1E4E8\"> (error) {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">        return</span><span style=\"color:#E1E4E8\"> { </span><span style=\"color:#F97583\">...</span><span style=\"color:#E1E4E8\">current, isSubmitting: </span><span style=\"color:#79B8FF\">false</span><span style=\"color:#E1E4E8\">, error };</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    }</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    return</span><span style=\"color:#E1E4E8\"> current;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"performance-considerations\" data-line=\"250\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#performance-considerations\" aria-hidden=\"true\"></a> Performance considerations</h2>\n<p data-line=\"252\" class=\"code-line\">The choice affects performance. Computed Signals need memory to track dependencies but recompute only when dependencies change, which is efficient. Linked Signals need memory for the previous value and run the callback on every source change.</p>\n<p data-line=\"254\" class=\"code-line\">Angular's runtime optimizes Computed Signals automatically. For Linked Signals, you may need manual optimization in some cases.</p>\n<h2 id=\"summary\" data-line=\"256\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#summary\" aria-hidden=\"true\"></a> Summary</h2>\n<p data-line=\"258\" class=\"code-line\">Understanding Signal, Computed Signal, and Linked Signal—and using each appropriately—helps you manage Angular application state more efficiently.</p>\n<p data-line=\"260\" class=\"code-line\">Use basic Signals for simple state, Computed Signals for values derived from other Signals, and Linked Signals when you need previous values or more complex transitions.</p>\n<p data-line=\"262\" class=\"code-line\">Computed Signals favor performance; Linked Signals favor direct updates from external events.</p>\n<p data-line=\"264\" class=\"code-line\">Using Signals well leads to more maintainable Angular applications.</p>\n<p data-line=\"266\" class=\"code-line\">See you next time.</p>\n","headings":[{"id":"signals-basics-recap","text":"Signals basics recap","level":2},{"id":"signal%2C-computed-signal%2C-and-linked-signal","text":"Signal, computed signal, and linked signal","level":2},{"id":"signal-(basic-signal)","text":"Signal (basic signal)","level":3},{"id":"computed-signal","text":"Computed Signal","level":3},{"id":"linked-signal","text":"Linked Signal","level":3},{"id":"which-should-you-use%3F-concrete-criteria","text":"Which should you use? Concrete criteria","level":2},{"id":"when-to-use-computed-signal","text":"When to use computed signal","level":3},{"id":"when-to-use-linked-signal","text":"When to use linked signal","level":3},{"id":"practical-example%3A-form-validation","text":"Practical example: form validation","level":2},{"id":"performance-considerations","text":"Performance considerations","level":2},{"id":"summary","text":"Summary","level":2}]} as const;
